pub enum Command {
    // the existing variants stay
    /// Compare the file on disk with the last read and set `FileState::disk_change`.
    CheckDisk,
}

/// Read the bytes at the document path and call `FileState::note_disk`.
/// A document without a path returns Ok(()). A missing file notes exists false.
fn check_disk_cmd(ws: &mut Workspace, view: ViewId) -> Result<(), CommandError>
